import{escapeHtml,filterNews,newsCard}from './news-utils.js';
import{getNewsIndex,getNewsItems}from './news-store.js';
export function mountNews(root){const $=s=>root.querySelector(s);let index,page=1,revision=0;const size=12;let saved;try{saved=new Set(JSON.parse(localStorage.getItem('polymer-atlas-news-favorites')||'[]'))}catch{saved=new Set()}
function options(selector,values){$(selector).innerHTML+=values.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join('')}
async function render(){if(!index)return;try{saved=new Set(JSON.parse(localStorage.getItem('polymer-atlas-news-favorites')||'[]'))}catch{saved=new Set()}const rev=++revision;const filters={query:$('#newsSearch').value,material:$('#newsMaterial').value,kind:$('#newsKind').value,month:$('#newsMonth').value,includeBackground:$('#includeBackground').checked};const active=!!(filters.query||filters.material||filters.kind||filters.month||$('#savedNews').checked);$('#newsCount').textContent='正在载入…';$('#prevPage').disabled=true;$('#nextPage').disabled=true;try{const loaded=await getNewsItems({month:filters.month,all:active,limit:page*size});if(rev!==revision)return;const items=filterNews(loaded,filters).filter(x=>!$('#savedNews').checked||saved.has(x.id));const count=active?items.length:index.total;const pages=Math.max(1,Math.ceil(count/size));page=Math.min(page,pages);$('#newsCount').textContent=`${count} 条消息`;$('#newsList').innerHTML=items.length?items.slice((page-1)*size,page*size).map(x=>newsCard(x,saved.has(x.id))).join(''):'<div class="empty"><h3>这个筛选下还没有消息</h3><p>试试其他材料或月份。</p></div>';$('#prevPage').disabled=page===1;$('#nextPage').disabled=page===pages;$('#pageLabel').textContent=`第 ${page} / ${pages} 页`;}catch{if(rev!==revision)return;$('#newsCount').textContent='载入失败';$('#newsList').innerHTML='<div class="empty"><h3>动态暂时未能载入</h3><p>请点击清除筛选重试。</p></div>';$('#prevPage').disabled=page===1;$('#nextPage').disabled=false;}}
for(const id of ['#newsMaterial','#newsKind','#newsMonth','#includeBackground','#savedNews'])$(id).addEventListener('change',()=>{page=1;render()});let searchTimer;$('#newsSearch').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page=1;render()},180)});
$('#clearFilters').addEventListener('click',()=>{for(const id of ['#newsMaterial','#newsKind','#newsMonth','#newsSearch'])$(id).value='';$('#includeBackground').checked=false;$('#savedNews').checked=false;page=1;render()});$('#prevPage').addEventListener('click',()=>{page=Math.max(1,page-1);render()});$('#nextPage').addEventListener('click',()=>{page++;render()});
$('#newsList').addEventListener('click',ev=>{const b=ev.target.closest('[data-news-save]');if(!b)return;const id=b.dataset.newsSave;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('polymer-atlas-news-favorites',JSON.stringify([...saved]))}catch{}if(window.dispatchEvent)window.dispatchEvent(new Event('atlas-favorites-changed'));render()});
window.addEventListener('atlas-favorites-changed',()=>{if(index)render()});
const ready=(async()=>{try{index=await getNewsIndex();options('#newsMaterial',index.materials);options('#newsKind',index.kinds);options('#newsMonth',index.months.map(x=>x.month));$('#total').textContent=`已归档 ${index.total} 条消息`;$('#lastCheck').textContent=`最近检索：${index.checked_at||index.updated_at}`;await render()}catch{$('#total').textContent='暂时未能载入';$('#newsList').innerHTML='<div class="empty"><h3>动态暂时未能载入</h3><p>请刷新页面重试。</p></div>'}})();return{ready};}
